// Bài của trang trong 3 ngày gần nhất: chỉ trả lời comment dưới các bài này.
const MY_USERNAME = 'toeicmasteryy';
const since = Date.now() - 3 * 24 * 60 * 60 * 1000;
const posts = ($input.first().json.data || []).filter((p) => p.timestamp && Date.parse(p.timestamp) >= since && !p.is_reply);
return posts.map((p) => ({ json: { postId: p.id, postText: p.text || '', MY_USERNAME } }));

// Comment chưa trả lời, không phải của trang, tối đa 5 cái mỗi lần chạy.
const MAX_PER_RUN = 5;
const posts = $('📋 Chọn bài gần đây').all().map((i) => i.json);
const store = $getWorkflowStaticData('global');
const handled = new Set(store.handledReplyIds || []);

const todo = [];
$input.all().forEach((item, i) => {
  const post = posts[i];
  for (const c of item.json.data || []) {
    if (!c.text || !c.username || c.username === post.MY_USERNAME) continue;
    if (handled.has(c.id)) continue;
    // Đã có trả lời của trang ngay dưới comment này thì bỏ qua.
    const answered = (item.json.data || []).some((r) => r.username === post.MY_USERNAME && r.replied_to && r.replied_to.id === c.id);
    if (answered) { handled.add(c.id); continue; }
    todo.push({ commentId: c.id, commentText: c.text, commenter: c.username, postText: post.postText });
  }
});
store.handledReplyIds = [...handled].slice(-500);
return todo.slice(0, MAX_PER_RUN).map((t) => ({ json: t }));

// Câu trả lời không đạt hoặc AI bảo SKIP -> bỏ qua comment đó (không dừng cả lượt).
const BLOCKED = /study4|prep\.vn|dethitoeic|hochay|toeichanquoc|english mastery|mshoa|ms hoa|\bzim\b|ielts fighter|vocamax|ontoeic|openquiz/i;
const store = $getWorkflowStaticData('global');
const handled = new Set(store.handledReplyIds || []);
const items = $('🧹 Tạo prompt trả lời').all();

const ok = [];
$input.all().forEach((item, i) => {
  const t = items[i].json;
  handled.add(t.commentId); // đánh dấu đã xử lý dù đăng hay bỏ qua, để không lặp lại
  const parts = item.json.candidates?.[0]?.content?.parts || [];
  const reply = parts.filter((p) => !p.thought).map((p) => p.text || '').join('').replace(/\*\*/g, '').trim();
  const problems = [];
  if (!reply || /^SKIP\b/i.test(reply)) problems.push('AI bỏ qua (SKIP) hoặc không trả lời');
  if (reply.length > 300) problems.push('dài ' + reply.length + ' ký tự');
  if (/https?:\/\/|\b[a-z0-9-]+\.(vn|com|net|org|io|app|click|me|co)\b/i.test(reply)) problems.push('có link/tên miền');
  if (/\bfree\b|miễn phí|không cần (đăng nhập|đăng ký)/i.test(reply)) problems.push('nói free/không cần đăng nhập');
  if (/\d+([.,]\d+)?\s*%|tăng\s*\d+\s*điểm|cam kết/i.test(reply)) problems.push('số liệu/cam kết');
  if (BLOCKED.test(reply)) problems.push('nhắc thương hiệu khác');
  if (/(lời giải|giải thích) chi tiết|chép chính tả|radar/i.test(reply) && !/\bpro\b/i.test(reply)) problems.push('tính năng Pro không ghi Pro');
  if (problems.length) console.log('[bỏ qua] @' + t.commenter + ': ' + t.commentText + ' -> ' + problems.join(', ') + ' | ' + reply);
  else ok.push({ json: { ...t, reply } });
});
store.handledReplyIds = [...handled].slice(-500);
return ok;

return $('✅ Kiểm tra câu trả lời').all().map((item, i) => ({
  json: { comment: '@' + item.json.commenter + ': ' + item.json.commentText, traLoi: item.json.reply, replyId: $input.all()[i]?.json.id || null },
}));
